          "title": "Unicode Support",
          "story": "As a user, I want to be able to use Unicode, so that I can use any language I like.",
          "acceptance_criteria": []
        },
        {
          "title": "Sensible and Predictable URLs",
          "story": "As a user, I want to see sensible and predictable URLs, so that the application feels logical and transparent.",
          "acceptance_criteria": []
        },
        {
          "title": "User-Friendly Error Pages",
          "story": "As a user, I want to have nice error pages when something goes wrong, so that I can trust the system and its developers.",
          "acceptance_criteria": []
        },
        {
          "title": "Non-Identifiable Data Storage",
          "story": "As a Researcher, I want results to be stored in a non-identifiable way, so that I can study the data to see things like whether estimates converged around the first opinion given by 'estimator A'.",
          "acceptance_criteria": []
        }
      ]
    }
  ]
}
